/*---------------------------------------------------------------------------------------------
 *  Agent Configuration - YAML + JSON config with models.json support
 *  
 *  Resolution order:
 *    1. CLI flags (--profile, --model, etc.)
 *    2. Environment variables (OPENAI_API_KEY, LLM_MODEL, etc.)
 *    3. Project config.yaml / config.json (in CWD)
 *    4. Global ~/.agent/config.yaml / config.json (legacy ~/.codeagent still read)
 *    5. models.json (CodeBuddy-compatible, ~/.agent/models.json or ~/.codebuddy/models.json)
 *    6. Built-in defaults
 *--------------------------------------------------------------------------------------------*/

import * as fs from 'node:fs';
import * as path from 'node:path';
import * as os from 'node:os';
import { IAgentConfig, DEFAULT_AGENT_CONFIG } from 'vs/workbench/services/agent/common/agentModels';
import { agentHomeFileCandidates } from './agentHome';

/**
 * Remove a trailing YAML comment from a scalar value.
 *
 * A `#` starts a comment only at the start of the value or after whitespace, and
 * never inside quotes — so `base_url: http://host/#frag` and `secret_key: "sk-#1"`
 * survive, while `enabled: true  # on by default` does not keep the comment.
 *
 * The hand-written section parsers (`tracing:`, `self_update:`) rely on this: the
 * config file is documented in place, and feeding
 * `"https://cloud.langfuse.com   # 自建部署改成对应地址"` to a consumer fails.
 */
export function stripYamlComment(value: string): string {
	let quote = '';
	for (let i = 0; i < value.length; i++) {
		const ch = value[i];
		if (quote) {
			if (ch === quote) quote = '';
			continue;
		}
		if (ch === '"' || ch === "'") { quote = ch; continue; }
		if (ch === '#' && (i === 0 || /\s/.test(value[i - 1]))) {
			return value.slice(0, i);
		}
	}
	return value;
}

/** Parse a `key: value` scalar the way these config files are written by hand. */
export function parseScalarValue(raw: string): string {
	return stripYamlComment(raw).trim().replace(/^["']|["']$/g, '');
}

interface ConfigProfile {
	provider: string;
	model: string;
	api_key: string;
	api_base?: string;
	temperature?: number;
	top_k?: number;
	max_input_tokens?: number;
	max_output_tokens?: number;
}

/**
 * Model routing configuration — maps scenarios to specific models so the agent
 * can automatically pick and switch models within a session based on the prompt.
 *
 * config.yaml:
 *   model_routing:
 *     enabled: true
 *     default: deepseek-v4-flash
 *     scenarios:
 *       reasoning: deepseek-v4-pro
 *       vision: deepseek-v4-flash-vision-exp
 *       fast: deepseek-v4-flash
 */
export interface ModelRoutingConfig {
	enabled: boolean;
	defaultModel?: string;
	/**
	 * 保底模型 (guaranteed fallback). When the scenario/default model selected
	 * for a prompt times out (API access timeout), the agent automatically
	 * switches to this model and retries. Resolved from
	 * `model_routing.fallback` (a models.json id / profile name).
	 */
	fallbackModel?: string;
	/**
	 * How often the background probe re-checks the primary/scenario model while
	 * the agent runs on the 保底 model (ms). Resolved from
	 * `model_routing.fallback_probe_interval_s` (seconds). Undefined = built-in
	 * schedule (30s, backing off to 120s).
	 */
	probeIntervalMs?: number;
	scenarios?: Record<string, string>;
}

interface McpServerConfig {
	command?: string;
	args?: string[];
	env?: Record<string, string>;
	url?: string;
	type?: string;
	headers?: Record<string, string>;
	/** Optional allowlist of MCP tool names to expose from this server. */
	tools?: string[];
}

interface ConfigFile {
	active_profile?: string;
	profiles?: Record<string, ConfigProfile>;
	agent?: {
		max_steps?: number;
		max_context_tokens?: number;
		temperature?: number;
		top_k?: number;
		step_timeout?: number;
		task_timeout?: number;
	};
	skills?: string[];
	rules?: string[];
	mcp_servers?: Record<string, McpServerConfig>;
	model_routing?: {
		enabled?: boolean;
		default?: string;
		fallback?: string;
		fallback_probe_interval_s?: number;
		scenarios?: Record<string, string>;
	};
}

// CodeBuddy-compatible models.json entry
interface ModelEntry {
	id: string;
	name?: string;
	vendor?: string;
	apiKey: string;
	url: string;
	maxInputTokens: number;
	maxOutputTokens: number;
	supportsToolCall?: boolean;
	supportsImages?: boolean;
	supportsReasoning?: boolean;
	thinking?: { type: string };
	maxTokens?: number;
}

interface ModelsFile {
	models: ModelEntry[];
	availableModels?: string[];
}

function parseYaml(text: string): ConfigFile {
	const result: ConfigFile = {};
	const lines = text.split('\n');
	let currentSection = '';
	let currentProfile = '';
	let inList = false;
	let listKey = '';
	let inRoutingScenarios = false;
	let inMcpTools = false;

	for (const line of lines) {
		const trimmed = line.trimEnd();
		if (!trimmed || trimmed.trimStart().startsWith('#')) continue;

		const indent = line.length - line.trimStart().length;

		if (indent === 0 && trimmed.endsWith(':')) {
			currentSection = trimmed.slice(0, -1);
			currentProfile = '';
			inList = false;
			if (currentSection === 'profiles') result.profiles = result.profiles || {};
			if (currentSection === 'agent') result.agent = result.agent || {};
			if (currentSection === 'model_routing') result.model_routing = result.model_routing || {};
			continue;
		}

		if (indent === 0 && trimmed.includes(':')) {
			const [key, ...rest] = trimmed.split(':');
			const val = rest.join(':').trim();
			if (key.trim() === 'active_profile') result.active_profile = val;
			continue;
		}

		if (currentSection === 'profiles' && indent === 2 && trimmed.endsWith(':')) {
			currentProfile = trimmed.slice(0, -1).trim();
			result.profiles![currentProfile] = { provider: '', model: '', api_key: '' };
			continue;
		}

		if (currentSection === 'profiles' && indent === 4 && currentProfile) {
			const [key, ...rest] = trimmed.split(':');
			const val = rest.join(':').trim();
			const k = key.trim();
			const profile = result.profiles![currentProfile];
			if (k === 'provider') profile.provider = val;
			else if (k === 'model') profile.model = val;
			else if (k === 'api_key') profile.api_key = val.replace(/^["']|["']$/g, '');
			else if (k === 'api_base') profile.api_base = val;
			else if (k === 'temperature') profile.temperature = parseFloat(val);
			else if (k === 'top_k') profile.top_k = parseInt(val, 10);
			else if (k === 'max_input_tokens') profile.max_input_tokens = parseInt(val, 10);
			else if (k === 'max_output_tokens') profile.max_output_tokens = parseInt(val, 10);
			continue;
		}

		if (currentSection === 'agent' && indent === 2) {
			const [key, ...rest] = trimmed.split(':');
			const val = rest.join(':').trim();
			const k = key.trim();
			if (!result.agent) result.agent = {};
			if (k === 'max_steps') result.agent.max_steps = parseInt(val, 10);
			else if (k === 'max_context_tokens') result.agent.max_context_tokens = parseInt(val, 10);
			else if (k === 'temperature') result.agent.temperature = parseFloat(val);
			else if (k === 'top_k') result.agent.top_k = parseInt(val, 10);
			else if (k === 'step_timeout') result.agent.step_timeout = parseInt(val, 10);
			else if (k === 'task_timeout') result.agent.task_timeout = parseInt(val, 10);
			continue;
		}

		if (currentSection === 'model_routing') {
			if (!result.model_routing) result.model_routing = {};
			if (indent === 2 && trimmed.endsWith(':')) {
				const subKey = trimmed.slice(0, -1).trim();
				inRoutingScenarios = subKey === 'scenarios';
				if (inRoutingScenarios) result.model_routing.scenarios = result.model_routing.scenarios || {};
				continue;
			}
			if (indent === 2) {
				const [key, ...rest] = trimmed.split(':');
				const val = rest.join(':').trim();
				const k = key.trim();
				if (k === 'enabled') result.model_routing.enabled = val === 'true' || val === '1' || val === 'yes';
				else if (k === 'default') result.model_routing.default = val;
				else if (k === 'fallback') result.model_routing.fallback = val;
				else if (k === 'fallback_probe_interval_s') result.model_routing.fallback_probe_interval_s = parseFloat(val);
				continue;
			}
			if (indent === 4 && inRoutingScenarios) {
				const [key, ...rest] = trimmed.split(':');
				const val = rest.join(':').trim();
				if (result.model_routing.scenarios) {
					result.model_routing.scenarios[key.trim()] = val;
				}
				continue;
			}
		}

		if (currentSection === 'mcp_servers' && indent === 2 && trimmed.endsWith(':')) {
			currentProfile = trimmed.slice(0, -1).trim();
			if (!result.mcp_servers) result.mcp_servers = {};
			result.mcp_servers[currentProfile] = {};
			continue;
		}

		if (currentSection === 'mcp_servers' && indent === 4 && currentProfile) {
			const [key, ...rest] = trimmed.split(':');
			const val = rest.join(':').trim();
			const k = key.trim();
			const srv = result.mcp_servers![currentProfile];
			inMcpTools = (k === 'tools');
			if (k === 'command') srv.command = val;
			else if (k === 'url') srv.url = val;
			else if (k === 'type') srv.type = val;
			else if (k === 'headers') {
				if (!srv.headers) srv.headers = {};
				// headers section starts
			}
			else if (k === 'tools') {
				if (!srv.tools) srv.tools = [];
				// tools allowlist starts
			}
			else if (k === 'args') {
				// single-line shorthand: args: --port 8080
				if (val) srv.args = val.split(/\s+/);
			}
			continue;
		}

		if (currentSection === 'mcp_servers' && indent === 6 && currentProfile) {
			const srv = result.mcp_servers?.[currentProfile];
			if (srv && inMcpTools && trimmed.trimStart().startsWith('- ')) {
				// tools allowlist item
				if (!srv.tools) srv.tools = [];
				srv.tools.push(trimmed.trimStart().slice(2).trim());
			} else if (srv && trimmed.trimStart().startsWith('- ')) {
				// args list item
				const val = trimmed.trimStart().slice(2).trim();
				if (!srv.args) srv.args = [];
				srv.args.push(val);
			} else if (srv && srv.headers !== undefined) {
				// headers key-value pair
				const [key, ...rest] = trimmed.split(':');
				const val = rest.join(':').trim();
				srv.headers[key.trim()] = val;
			}
			continue;
		}

		if (currentSection === 'mcp_servers' && indent === 6 && trimmed.trimStart().startsWith('- ')) {
			const val = trimmed.trimStart().slice(2).trim();
			const srv = result.mcp_servers?.[currentProfile];
			if (srv) {
				if (!srv.args) srv.args = [];
				srv.args.push(val);
			}
			continue;
		}

		if ((currentSection === 'skills' || currentSection === 'rules') && trimmed.trimStart().startsWith('- ')) {
			const val = trimmed.trimStart().slice(2).trim();
			if (!result[currentSection as 'skills' | 'rules']) {
				(result as any)[currentSection] = [];
			}
			(result as any)[currentSection].push(val);
			continue;
		}
	}

	return result;
}

function findConfigFile(): string | undefined {
	const candidates = [
		path.join(process.cwd(), 'config.yaml'),
		path.join(process.cwd(), 'config.json'),
		...agentHomeFileCandidates('config.yaml'),
		...agentHomeFileCandidates('config.json'),
	];
	return candidates.find(p => fs.existsSync(p));
}

function findModelsJson(): string | undefined {
	const candidates = [
		path.join(process.cwd(), 'models.json'),
		...agentHomeFileCandidates('models.json'),
		path.join(os.homedir(), '.codebuddy', 'models.json'),  // shared compat
	];
	return candidates.find(p => fs.existsSync(p));
}

/** Convert a models.json ModelEntry to a ConfigProfile */
function modelEntryToProfile(entry: ModelEntry): ConfigProfile {
	// Strip /chat/completions suffix if present, to get base URL
	const apiBase = entry.url.replace(/\/chat\/completions\/?$/, '');
	return {
		provider: 'openai',
		model: entry.id,
		api_key: entry.apiKey,
		api_base: apiBase,
		max_input_tokens: entry.maxInputTokens,
		max_output_tokens: entry.maxOutputTokens || entry.maxTokens,
	};
}

/** Load models from a CodeBuddy-compatible models.json file */
function loadModelsJson(): Record<string, ConfigProfile> | undefined {
	const modelsPath = findModelsJson();
	if (!modelsPath) return undefined;

	try {
		const raw = fs.readFileSync(modelsPath, 'utf-8');
		const data: ModelsFile = JSON.parse(raw);
		const profiles: Record<string, ConfigProfile> = {};
		for (const entry of data.models) {
			profiles[entry.id] = modelEntryToProfile(entry);
		}
		return profiles;
	} catch {
		return undefined;
	}
}

function resolveHomePath(p: string): string {
	if (p.startsWith('~/') || p.startsWith('~\\')) {
		return path.join(os.homedir(), p.slice(2));
	}
	return path.resolve(p);
}

export interface McpServerEntry {
	name: string;
	command?: string;
	args?: string[];
	env?: Record<string, string>;
	url?: string;
	type?: string;
	headers?: Record<string, string>;
	/** Optional allowlist of MCP tool names to expose from this server. */
	tools?: string[];
}

export interface ResolvedConfig {
	agentConfig: IAgentConfig;
	skillsDirs: string[];
	rulesDirs: string[];
	profileName: string;
	configFilePath?: string;
	mcpServers: McpServerEntry[];
	/** All available model configs keyed by model id / profile name — used for model routing. */
	profiles: Record<string, IAgentConfig>;
	/** Scenario → model routing configuration. */
	modelRouting: ModelRoutingConfig;
	/**
	 * Whether the profile was explicitly pinned on the command line (--profile).
	 * Only then is model routing disabled, so the agent never switches to another
	 * model at runtime. Without a --profile flag, auto model selection stays
	 * enabled even when config.yaml sets active_profile or AGENT_PROFILE is set.
	 */
	profileExplicit: boolean;
}

/** Build a full IAgentConfig from a single profile (no env LLM_MODEL/provider override). */
function profileToAgentConfig(profile: ConfigProfile, agent: ConfigFile['agent']): IAgentConfig {
	const budgets = normalizeTokenBudgets(
		profile.max_input_tokens || agent?.max_context_tokens || DEFAULT_AGENT_CONFIG.maxContextTokens,
		profile.max_output_tokens || DEFAULT_AGENT_CONFIG.maxOutputTokens,
	);
	return {
		...DEFAULT_AGENT_CONFIG,
		provider: (profile.provider || DEFAULT_AGENT_CONFIG.provider) as IAgentConfig['provider'],
		model: profile.model || DEFAULT_AGENT_CONFIG.model,
		apiKey: profile.api_key || process.env.OPENAI_API_KEY || process.env.ANTHROPIC_API_KEY || '',
		apiBase: profile.api_base || undefined,
		maxSteps: agent?.max_steps || DEFAULT_AGENT_CONFIG.maxSteps,
		maxContextTokens: budgets.maxContextTokens,
		maxOutputTokens: budgets.maxOutputTokens,
		temperature: profile.temperature ?? agent?.temperature ?? DEFAULT_AGENT_CONFIG.temperature,
		topK: profile.top_k ?? agent?.top_k ?? DEFAULT_AGENT_CONFIG.topK,
		stepTimeout: agent?.step_timeout || DEFAULT_AGENT_CONFIG.stepTimeout,
		taskTimeout: agent?.task_timeout || DEFAULT_AGENT_CONFIG.taskTimeout,
	};
}

/** Minimum token budget that must remain available for input after reserving the completion budget. */
const MIN_INPUT_BUDGET = 4096;

/**
 * Where skills/rules live when config.yaml does not say. `~/.agent` is the
 * current home; `~/.codeagent` and `~/.cursor` stay supported so an existing
 * installation keeps working without editing its config.
 */
const DEFAULT_SKILLS_DIRS = ['~/.agent/skills', '~/.codeagent/skills', '~/.cursor/skills'];
const DEFAULT_RULES_DIRS = ['~/.agent/rules', '~/.codeagent/rules', '~/.cursor/rules'];

/**
 * Normalize context/output token budgets so the completion reservation can never
 * consume the entire context window. Without this, maxOutputTokens >= maxInputTokens
 * leaves zero room for messages and triggers "maximum context length" API errors.
 *
 * maxContextTokens is treated as the model's TOTAL context window (input + output
 * share the same pool, e.g. deepseek-v4 = 1048576 tokens); maxOutputTokens is the
 * completion reservation and is capped to leave at least MIN_INPUT_BUDGET tokens
 * for input.
 */
function normalizeTokenBudgets(maxContextTokens: number, maxOutputTokens: number): { maxContextTokens: number; maxOutputTokens: number } {
	const context = Math.max(1, maxContextTokens || 0);
	const output = Math.max(1, maxOutputTokens || 0);
	const maxAllowedOutput = Math.max(1, context - MIN_INPUT_BUDGET);
	return {
		maxContextTokens: context,
		maxOutputTokens: Math.min(output, maxAllowedOutput),
	};
}

export function loadConfig(cliProfile?: string): ResolvedConfig {
	let fileConfig: ConfigFile = {};
	const configPath = findConfigFile();

	if (configPath) {
		try {
			const raw = fs.readFileSync(configPath, 'utf-8');
			fileConfig = configPath.endsWith('.json')
				? JSON.parse(raw) as ConfigFile
				: parseYaml(raw);
		} catch {
			// ignore parse errors, fall through to env/defaults
		}
	}

	// Load models from models.json (CodeBuddy-compatible format)
	const modelsProfiles = loadModelsJson();
	if (modelsProfiles) {
		// Merge: models.json provides model definitions, config.yaml profiles take precedence
		fileConfig.profiles = { ...modelsProfiles, ...fileConfig.profiles };
	}

	// Resolve profile name with smart default: if only models.json is available
	// and no active_profile is set, auto-select the first model
	let profileName = cliProfile
		|| process.env.AGENT_PROFILE
		|| fileConfig.active_profile
		|| undefined;

	// True only when the user pinned a profile on the command line (--profile).
	// In that case model routing must be disabled so the agent never switches to
	// another model mid-run. AGENT_PROFILE / active_profile still select the
	// initial model, but do not disable automatic routing.
	const profileExplicit = !!cliProfile;

	if (!profileName && fileConfig.profiles && Object.keys(fileConfig.profiles).length > 0) {
		profileName = Object.keys(fileConfig.profiles)[0];
	} else if (!profileName) {
		profileName = 'default';
	}

	let profile = fileConfig.profiles?.[profileName];
	if (fileConfig.profiles && !profile && profileName !== 'default') {
		const available = Object.keys(fileConfig.profiles).join(', ');
		console.warn(`Warning: profile "${profileName}" not found in config. Available: ${available}`);
		// Auto-fallback to first available model
		profileName = Object.keys(fileConfig.profiles)[0];
		profile = fileConfig.profiles?.[profileName];
		console.warn(`         Falling back to: "${profileName}"`);
	}

	const budgets = normalizeTokenBudgets(
		profile?.max_input_tokens || fileConfig.agent?.max_context_tokens || DEFAULT_AGENT_CONFIG.maxContextTokens,
		profile?.max_output_tokens || DEFAULT_AGENT_CONFIG.maxOutputTokens,
	);

	const agentConfig: IAgentConfig = {
		...DEFAULT_AGENT_CONFIG,
		provider: (process.env.LLM_PROVIDER || profile?.provider || DEFAULT_AGENT_CONFIG.provider) as any,
		model: process.env.LLM_MODEL || profile?.model || DEFAULT_AGENT_CONFIG.model,
		apiKey: process.env.OPENAI_API_KEY || process.env.ANTHROPIC_API_KEY || profile?.api_key || '',
		apiBase: process.env.LLM_API_BASE || profile?.api_base || undefined,
		maxSteps: fileConfig.agent?.max_steps || DEFAULT_AGENT_CONFIG.maxSteps,
		maxContextTokens: budgets.maxContextTokens,
		maxOutputTokens: budgets.maxOutputTokens,
		temperature: profile?.temperature ?? fileConfig.agent?.temperature ?? DEFAULT_AGENT_CONFIG.temperature,
		topK: profile?.top_k ?? fileConfig.agent?.top_k ?? DEFAULT_AGENT_CONFIG.topK,
		stepTimeout: fileConfig.agent?.step_timeout || DEFAULT_AGENT_CONFIG.stepTimeout,
		taskTimeout: fileConfig.agent?.task_timeout || DEFAULT_AGENT_CONFIG.taskTimeout,
	};

	const skillsDirs = (fileConfig.skills || DEFAULT_SKILLS_DIRS).map(resolveHomePath);
	const rulesDirs = (fileConfig.rules || DEFAULT_RULES_DIRS).map(resolveHomePath);

	const mcpServers: McpServerEntry[] = Object.entries(fileConfig.mcp_servers || {}).map(
		([name, srv]) => ({ name, ...srv })
	);

	// Build all available model configs (models.json + config.yaml profiles) for routing.
	const profiles: Record<string, IAgentConfig> = {};
	for (const [name, p] of Object.entries(fileConfig.profiles || {})) {
		profiles[name] = profileToAgentConfig(p, fileConfig.agent);
	}

	// Model routing: enabled only when a model_routing section is present, not
	// explicitly disabled, AND no profile was explicitly configured. When the
	// user pins a profile (--profile / AGENT_PROFILE / active_profile) the model
	// is fixed and must never be swapped at runtime.
	const hasRouting = fileConfig.model_routing !== undefined;
	const probeSeconds = fileConfig.model_routing?.fallback_probe_interval_s;
	const modelRouting: ModelRoutingConfig = {
		enabled: hasRouting && fileConfig.model_routing?.enabled !== false && !profileExplicit,
		defaultModel: fileConfig.model_routing?.default,
		fallbackModel: fileConfig.model_routing?.fallback,
		probeIntervalMs: typeof probeSeconds === 'number' && probeSeconds > 0 ? probeSeconds * 1000 : undefined,
		scenarios: fileConfig.model_routing?.scenarios || {},
	};

	return {
		agentConfig,
		skillsDirs,
		rulesDirs,
		profileName,
		configFilePath: configPath,
		mcpServers,
		profiles,
		modelRouting,
		profileExplicit,
	};
}

export function loadConfigForProfile(profileName: string): ResolvedConfig {
	return loadConfig(profileName);
}

export function listProfiles(): Array<{ name: string; provider: string; model: string }> {
	// First check models.json
	const modelsProfiles = loadModelsJson();
	if (modelsProfiles) {
		return Object.entries(modelsProfiles).map(([name, p]) => ({
			name,
			provider: p.provider,
			model: p.model,
		}));
	}

	// Fall back to config.yaml
	const configPath = findConfigFile();
	if (!configPath) return [];

	try {
		const raw = fs.readFileSync(configPath, 'utf-8');
		const config = parseYaml(raw);
		return Object.entries(config.profiles || {}).map(([name, p]) => ({
			name,
			provider: p.provider,
			model: p.model,
		}));
	} catch {
		return [];
	}
}
